import{z as i,x as o,o as t,c,q as l,j as B,D as e,d as s,s as A,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"动态树与 LCT","description":"","frontmatter":{"title":"动态树与 LCT","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/link-cut-tree.md","filePath":"cs/link-cut-tree.md","lastUpdated":1791413859000}'),p={name:"cs/link-cut-tree.md"};function d(D,E,m,u,C,T){const r=o("Mermaid");return t(),c("div",null,[E[2]||(E[2]=l('<h1 id="动态树与-lct" tabindex="-1">动态树与 LCT <a class="header-anchor" href="#动态树与-lct" aria-label="Permalink to &quot;动态树与 LCT&quot;">​</a></h1><div class="epigraph"><p>树一旦允许 link 与 cut，任何一次排好的 DFS 序都会作废；LCT 用偏好路径把「结构在变」摊还进每次访问，单操作摊还 $O(\\log n)$。</p><footer>—— 据 Sleator 与 Tarjan, A Data Structure for Dynamic Trees, 1983</footer></div><p><a href="/cs/ae-case-map">算法工程案例与收束</a>把整条算法主线收进了案例——案例里的结构都是静态的。算法里常碰到的树却不冻结：<a href="/cs/tree-binary-lifting">tree-binary-lifting</a> 的倍增表、树剖的重链划分，都默认树不再长枝。缺口是 <strong>动态树</strong>：边会连、会断，路径聚合还得照答。本课写 LCT——不是把静态剖分搬来重跑，而是换一套随时重划的链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态树上路径求和走树剖加 <a href="/cs/segment-tree">segment-tree</a>，LCA 走倍增；一次 cut 让子树归属全变，DFS 序整段报废，重建一遍是 \\(O(n)\\)，混进 \\(10^5\\) 次增删就是灾难。缺口：支持 link（连边）、cut（断边）、换根、路径查询修改的结构。本课不写 splay 摊还证明的全推导，也不展开子树聚合的虚儿子维护——那是软肋，下一课补。</p><p><span class="marginnote">术语翻译：preferred path 译作「偏好路径」，preferred child 译作「偏好儿子」；LCT 实为一个「辅助树森林」——真树不动，动的只是每条偏好链在 splay 树里的挂法。辅助树之间由虚边相连，虚边指向本链挂靠的上一层点。</span></p><p><span class="marginnote">数字实例：\\(10^5\\) 次混有 link/cut 的操作，朴素方案每次重建序要 \\(O(n)\\)，合计 \\(10^{10}\\) 级别；LCT 摊还 \\(O(\\log n)\\)，合计约 \\(10^5\\times 17\\)，差了近四个数量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核心操作只有一个 <strong>access</strong>：把 \\(v\\) 到真根的路径拉成一条偏好路径，路径信息随之集中进一棵辅助树。makeroot（换根，翻转路径的懒标记）、link、cut 全是 access 的组合：cut 先 makeroot 再 access 再断链，link 先 makeroot 一端再挂到另一端。</p>',9)),(t(),B(n,null,{default:e(()=>[A(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%93%8D%E4%BD%9C%20access%20v%22%5D%20--%3E%20B%5B%22%E4%BB%8E%20v%20%E6%89%80%E5%9C%A8%E8%BE%85%E5%8A%A9%E6%A0%91%E5%87%BA%E5%8F%91%20splay%20v%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%96%AD%E5%BC%80%20v%20%E7%9A%84%E5%8F%B3%E5%84%BF%E5%AD%90%EF%BC%9A%E8%B7%AF%E5%BE%84%E5%88%B0%E6%AD%A4%E4%B8%BA%E6%AD%A2%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%B2%BF%E8%99%9A%E8%BE%B9%E8%B7%B3%E5%90%91%E4%B8%8A%E4%B8%80%E5%B1%82%E8%BE%85%E5%8A%A9%E6%A0%91%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%88%87%E6%8D%A2%E5%81%8F%E5%A5%BD%E5%84%BF%E5%AD%90%EF%BC%9A%E6%97%A7%E5%81%8F%E5%A5%BD%E9%93%BE%E9%99%8D%E7%BA%A7%E4%B8%BA%E8%99%9A%E8%BE%B9%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%87%8D%E5%A4%8D%E7%9B%B4%E5%88%B0%20v%20%E4%B8%8E%E7%9C%9F%E6%A0%B9%E5%90%8C%E9%93%BE%22%5D%0A%20%20F%20--%3E%20G%5B%22%E8%B7%AF%E5%BE%84%E8%81%9A%E5%90%88%E5%8F%AA%E7%A2%B0%E6%9C%80%E5%90%8E%E8%BF%99%E6%A3%B5%E8%BE%85%E5%8A%A9%E6%A0%91%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"七步里只有 splay 与断右儿子真正改树形，其余是标记与指针搬动。写实现先把 access 打磨对，再往上叠 makeroot 与 link/cut，顺序反了会 debug 到怀疑人生。",-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：偏好路径像公交公司每天重新划的快车专线——街道（真树）没变，只是「今天这条路上走快线」的标记在变。access 就是重新划线：要去的路线涂成专线，别的线降级。划线的成本被均摊进每次乘车。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[s("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"为什么摊还 \\(O(\\log n)\\)：splay 自身的摊还界管住辅助树内部；access 中切换偏好儿子的次数另有硬上限——每次被降级的原偏好儿子按重轻边性质必连一条轻边，而任意点到根的轻边不超过 \\(O(\\log n)\\) 条。两个对数界相加，总摊还仍是对数。偏好儿子是给辅助树森林的标记，真树上没有「链」这层概念，换根、翻转才不至于改乱真实结构。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"常见误区：以为 access 会把整棵真树压成一条链。真树一个字节没动，变的只有偏好标记与辅助树形态；错在把「辅助树里的链」读成「真树的链」，于是写出「access 后 \\(v\\) 是全树根」这类断言——\\(v\\) 只是偏好路径的底端。")],-1)),(t(),B(n,null,{default:e(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E9%9D%99%E6%80%81%E6%A0%91%E5%89%96%EF%BC%9A%E9%87%8D%E9%93%BE%E4%B8%80%E6%AC%A1%E5%88%92%E6%AD%BB%22%5D%20--%3E%20SQ%5B%22%E6%9F%A5%E8%AF%A2%E6%B2%BF%E5%9B%BA%E5%AE%9A%E9%87%8D%E9%93%BE%E8%B5%B0%E6%AE%B5%22%5D%0A%20%20D%5B%22LCT%EF%BC%9A%E9%87%8D%E9%93%BE%E9%9A%8F%20access%20%E9%87%8D%E5%88%92%22%5D%20--%3E%20DQ%5B%22%E6%9F%A5%E8%AF%A2%E5%89%8D%E5%85%88%20access%20%E6%8B%89%E9%93%BE%22%5D%0A%20%20SQ%20--%3E%20A1%5B%22%E7%AD%94%E6%A1%88%E5%9C%A8%E5%9B%BA%E5%AE%9A%E6%AE%B5%E4%B8%8A%E6%9F%A5%EF%BC%8C%E6%AE%B5%E6%AE%B5%E9%83%BD%E8%A6%81%E7%88%AC%22%5D%0A%20%20DQ%20--%3E%20A2%5B%22%E9%93%BE%E6%8B%89%E7%9B%B4%E5%90%8E%E4%BF%A1%E6%81%AF%E9%9B%86%E4%B8%AD%EF%BC%8C%E4%B8%80%E6%AE%B5%E8%AF%BB%E5%AE%8C%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=l('<p>对照读：树剖赢在常数与实现简单，LCT 赢在链可以随时重划。同一道题能静态做就别上 LCT。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LCT 主场是路径聚合、连通性维护、动态最小生成树（边权变更时按权试连试断）。子树和、子树最值要给每个点额外记「虚儿子信息之和」，换根时增量更新，实现难度跳一档——这恰是下一课欧拉序的主场，那边子树信息顺手、路径信息变难，两种结构互为镜像。</p><p><span class="marginnote">常见误区：在纯静态题上用 LCT 交卷——能过，但常数是树剖的数倍，还多养一套翻转标记。选型判据一句话：结构会不会变；会变才轮到 LCT。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>access 把 \\(v\\) 到根拉成偏好路径，makeroot/link/cut 全是它的组合。</li><li>摊还 \\(O(\\log n)\\) 来自 splay 摊还界加重轻边性质双重夹逼。</li><li>真树不变，变的只有偏好标记——想通这点，翻转与换根才写不错。</li><li>子树聚合是软肋，下一课的欧拉序补那一面。</li><li>出处：Sleator 与 Tarjan, <em>A Data Structure for Dynamic Trees</em>, JCSS 1983；splay 摊还分析见同作者 <em>Self-Adjusting Binary Search Trees</em>, 1985。</li></ul>',6))])}const h=i(p,[["render",d]]);export{F as __pageData,h as default};
